$ErrorActionPreference = 'Stop'
$repair = 'C:\Users\kingd\AppData\Local\Temp\McpServer-G1-Repair-20260911'
$out = 'C:\Users\kingd\AppData\Local\Temp\grok-goal-f348d6190bdb\implementer\ledger\21e5b43f'
Set-Location $repair
$sha = git rev-parse HEAD
if ($sha -ne '21e5b43f3bdc049f6a47a76eb0f85628d0754d8e') { throw "SHA $sha" }
$ids = Get-Content (Join-Path $out 'c107-identities.txt') | Where-Object { $_.Trim().Length -gt 0 }
$log = Join-Path $out 'c107-union.log'
"C107_START=$((Get-Date).ToUniversalTime().ToString('o')) count=$($ids.Count) SHA=$sha" | Set-Content $log
$passed = New-Object 'System.Collections.Generic.HashSet[string]'
$batchSize = 35
$batch = 0
for ($i = 0; $i -lt $ids.Count; $i += $batchSize) {
  $batch++
  $slice = $ids[$i..([Math]::Min($i + $batchSize - 1, $ids.Count - 1))]
  $filter = ($slice | ForEach-Object { 'FullyQualifiedName~' + $_ }) -join '|'
  $trxName = "c107-batch$batch.trx"
  "BATCH $batch size=$($slice.Count) trx=$trxName" | Add-Content $log
  & dotnet test 'tests\McpServer.Support.Mcp.Tests\McpServer.Support.Mcp.Tests.csproj' -c Debug --filter $filter --logger "trx;LogFileName=$trxName" --results-directory $out *>> $log
  "BATCH $batch EXIT=$LASTEXITCODE" | Add-Content $log
  $trx = Join-Path $out $trxName
  [xml]$x = Get-Content $trx
  $defs = @{}
  foreach ($d in $x.TestRun.TestDefinitions.UnitTest) { $defs[$d.id] = $d.name }
  foreach ($r in $x.TestRun.Results.UnitTestResult) {
    if ($r.outcome -eq 'Passed') {
      $n = $defs[$r.testId]
      if (-not $n) { $n = $r.testName }
      [void]$passed.Add($n)
    }
  }
}
$missing = @($ids | Where-Object { -not $passed.Contains($_) })
"UNION_PASSED=$($passed.Count) MISSING=$($missing.Count)" | Add-Content $log
$missing | Set-Content (Join-Path $out 'c107-missing.txt')
$passed.Count | Set-Content (Join-Path $out 'c107-passed-count.txt')
if ($passed.Count -ne 107 -or $missing.Count -ne 0) { exit 1 }
"C107_OK=1 C107_END=$((Get-Date).ToUniversalTime().ToString('o'))" | Add-Content $log
exit 0

