"'$expected = @(Get-Content -LiteralPath (Join-Path $ledger '"'c107-identities.txt') | Where-Object { "'$_.Trim().Length -gt 0 } | Sort-Object -Unique)
$passed = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
Get-ChildItem -LiteralPath $ledger -Filter '"'c107-batch*.trx' | Sort-Object Name | ForEach-Object {
  [xml]"'$trx = Get-Content -Raw -LiteralPath $_.FullName
  $defs = @{}
  foreach ($def in $trx.TestRun.TestDefinitions.UnitTest) { $defs[[string]$def.id] = [string]$def.name }
  $batchPassed = 0
  $batchOther = 0
  foreach ($result in $trx.TestRun.Results.UnitTestResult) {
    if ([string]$result.outcome -eq '"'Passed') {
      "'$batchPassed++
      $name = $defs[[string]$result.testId]
      if (-not $name) { $name = [string]$result.testName }
      [void]$passed.Add($name)
    } else { $batchOther++ }
  }
  [pscustomobject]@{ Batch = $_.Name; PassedResults = $batchPassed; OtherResults = $batchOther }
} | Format-Table -AutoSize
$missing = @($expected | Where-Object { -not $passed.Contains($_) })
$extra = @($passed | Where-Object { $_ -notin $expected })
[pscustomobject]@{ ExpectedUnique = $expected.Count; PassedUnion = $passed.Count; Missing = $missing.Count; Extra = $extra.Count } | Format-List
if ($missing.Count) { '"'MISSING:'; "'$missing }
if ($extra.Count) { '"'EXTRA:'; "'$extra }'

